import cv2,numpy as np
im=cv2.imread('first_frame.png')[:,:,::-1]
hsv=cv2.cvtColor(im[:,:,::-1],cv2.COLOR_BGR2HSV)
# masks summaries cc
masks={'blue':((hsv[:,:,0]>85)&(hsv[:,:,0]<140)&(hsv[:,:,1]>60)), 'graybright':(hsv[:,:,1]<35)&(hsv[:,:,2]>120), 'dark':hsv[:,:,2]<55,'metal':(hsv[:,:,1]<60)&(hsv[:,:,2]>80)}
for n,m in masks.items():
 N,L,st,cent=cv2.connectedComponentsWithStats(m.astype('uint8'))
 print('\\n',n,m.sum())
 for i in np.argsort(st[1:,4])[-20:][::-1]+1:
  x,y,w,h,a=st[i];
  if a>5: print(a,(x,y,w,h),np.round(cent[i],1))
# tiles mean RGB and hsv by 16x12
print('\\nTile rgb means (rows 12 high, cols16):')
for y in range(0,144,12):
 print('ROW',y)
 print(' '.join('%02x%02x%02x'%tuple(im[y:y+12,x:x+16].mean((0,1)).astype(int)) for x in range(0,256,16)))
